import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';class SettingsCubit extends Cubit<SettingsState> with WidgetsBindingObserver {  SettingsCubit() : super(SettingsState()) {    WidgetsBinding.instance.addObserver(this);    _updateThemeMode();  }  @override  Future<void> close() {    WidgetsBinding.instance.removeObserver(this);    return super.close();  }  @override  void didChangePlatformBrightness() {    _updateThemeMode();  }  void _updateThemeMode() {    final brightness = WidgetsBinding.instance.window.platformBrightness;    final systemThemeMode =    brightness == Brightness.dark ? ThemeMode.dark : ThemeMode.light;    emit(state.copyWith(themeMode: systemThemeMode));  }  void toggleTheme() {    emit(state.copyWith(      themeMode:      state.themeMode == ThemeMode.light ? ThemeMode.dark : ThemeMode.light,    ));  }  void changeLanguage(Locale locale) {    emit(state.copyWith(locale: locale));  }}@immutableclass SettingsState {  final ThemeMode themeMode;  final Locale locale;  const SettingsState({    this.themeMode = ThemeMode.system,    this.locale = const Locale('ar'),  });  SettingsState copyWith({    ThemeMode? themeMode,    Locale? locale,  }) {    return SettingsState(      themeMode: themeMode ?? this.themeMode,      locale: locale ?? this.locale,    );  }}